-- ROCK9086 pass 14 (generated by gen_019.py): rows production logged under Fluid verification 2026-10-08..10-12.
-- Same output on DotLiquid: date-vs-string (Pastoral Nursing Home 30 / Homebound 26 entry form footers): the
--   Visit History edit/delete column test compared a DateTime to '08/2/2019'; DotLiquid parsed the string as a
--   date, Fluid did not, so the column disappeared on Fluid. The cutoff is now a DateTime (AsDateTime), which
--   both engines compare alike, including null and the cutoff day. LavaProbe cases D1-D13.
-- Guarded REPLACE per row, @DryRun = 1 rolls back, the live run is all-or-nothing, one backup per row to
-- dbo._ROCK9086_LavaBackup, rows absent from the target database log -1. Clear the Rock cache after.
SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
DECLARE @DryRun bit = 1;
DECLARE @log TABLE (Tbl sysname, Id int, FixRule varchar(40), [Rows] int);
DECLARE @avkeys TABLE (Id int, AttributeId int, EntityId int);
INSERT @avkeys VALUES (0, 0, 0);
BEGIN TRAN;

IF OBJECT_ID('dbo._ROCK9086_LavaBackup') IS NULL
    CREATE TABLE dbo._ROCK9086_LavaBackup (Tbl sysname NOT NULL, Id int NOT NULL, Col sysname NOT NULL, OldValue nvarchar(max) NULL, BackedUpAt datetime NOT NULL DEFAULT GETDATE());

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'WorkflowActionForm', x.[Id], 'Footer', x.[Footer] FROM [WorkflowActionForm] x WHERE x.[Id] = 26
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'WorkflowActionForm' AND b.Id = x.[Id] AND b.Col = 'Footer');
UPDATE [WorkflowActionForm] SET [Footer] = REPLACE([Footer], N'{% if lastActivityDate >= ''08/2/2019'' %}', N'{% assign actionsCutoff = ''2019-08-02'' | AsDateTime %}{% if lastActivityDate >= actionsCutoff %}')
WHERE [Id] = 26
  AND (DATALENGTH([Footer]) - DATALENGTH(REPLACE([Footer], N'{% if lastActivityDate >= ''08/2/2019'' %}', N''))) / DATALENGTH(N'{% if lastActivityDate >= ''08/2/2019'' %}') = 1;
INSERT @log VALUES ('WorkflowActionForm', 26, 'date-vs-string', @@ROWCOUNT);

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'WorkflowActionForm', x.[Id], 'Footer', x.[Footer] FROM [WorkflowActionForm] x WHERE x.[Id] = 30
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'WorkflowActionForm' AND b.Id = x.[Id] AND b.Col = 'Footer');
UPDATE [WorkflowActionForm] SET [Footer] = REPLACE([Footer], N'{% if lastActivityDate >= ''08/2/2019'' %}', N'{% assign actionsCutoff = ''2019-08-02'' | AsDateTime %}{% if lastActivityDate >= actionsCutoff %}')
WHERE [Id] = 30
  AND (DATALENGTH([Footer]) - DATALENGTH(REPLACE([Footer], N'{% if lastActivityDate >= ''08/2/2019'' %}', N''))) / DATALENGTH(N'{% if lastActivityDate >= ''08/2/2019'' %}') = 1;
INSERT @log VALUES ('WorkflowActionForm', 30, 'date-vs-string', @@ROWCOUNT);

UPDATE l SET [Rows] = -1 FROM @log l WHERE l.[Rows] = 0 AND NOT EXISTS (
    SELECT 1 FROM WorkflowType x WHERE l.Tbl = 'WorkflowType' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM HtmlContent x WHERE l.Tbl = 'HtmlContent' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM WorkflowActionForm x WHERE l.Tbl = 'WorkflowActionForm' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM SystemCommunication x WHERE l.Tbl = 'SystemCommunication' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM Block x WHERE l.Tbl = 'Block' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM ReportField x WHERE l.Tbl = 'ReportField' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM AttributeValue x JOIN @avkeys k ON k.Id = x.Id AND k.AttributeId = x.AttributeId AND k.EntityId = x.EntityId
        WHERE l.Tbl = 'AttributeValue' AND x.Id = l.Id);
SELECT * FROM @log ORDER BY Tbl, Id;
IF EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1)) PRINT 'WARNING: some statements did not update exactly one row - review before committing.';
IF @DryRun = 0 AND EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1))
BEGIN ROLLBACK; THROW 50000, 'ROCK9086 pass 14: a guarded update did not match exactly one row; nothing committed.', 1; END

SELECT 'WorkflowActionForm' Tbl, 26 Id, CASE WHEN CHARINDEX(N'{% if lastActivityDate >= ''08/2/2019'' %}' COLLATE Latin1_General_CS_AS, [Footer] COLLATE Latin1_General_CS_AS) > 0 THEN 1 ELSE 0 END StillOld FROM [WorkflowActionForm] WHERE [Id] = 26
UNION ALL
SELECT 'WorkflowActionForm' Tbl, 30 Id, CASE WHEN CHARINDEX(N'{% if lastActivityDate >= ''08/2/2019'' %}' COLLATE Latin1_General_CS_AS, [Footer] COLLATE Latin1_General_CS_AS) > 0 THEN 1 ELSE 0 END StillOld FROM [WorkflowActionForm] WHERE [Id] = 30;

IF @DryRun = 1 BEGIN ROLLBACK; PRINT 'Dry run - rolled back.'; END ELSE BEGIN COMMIT; PRINT 'Committed. Now clear the Rock cache.'; END
